samples.sql:
SELECT CDSCode
FROM schools
WHERE (Enrollment (K-12) + Enrollment (Ages 5-17)) > 500;

SELECT COUNT(*) FROM schools AS T1
JOIN satscores AS T2 ON T1.CDSCode = T2.cds
WHERE T1.County = 'Fresno' AND T1.FundingType = 'Direct' AND T2.NumTstTakr <= 250;

SELECT COUNT(CDSCode) / 12 AS MonthlyAverage
FROM schools
WHERE County = 'Alameda' AND DOC = 52;

SELECT SUM(CASE WHEN A3 = 'East Bohemia' THEN A16 ELSE 0 END) - SUM(CASE WHEN A3 = 'North Bohemia' THEN A16 ELSE 0 END) AS difference
FROM district
WHERE strftime('%Y', date) = '1996';

SELECT AVG(COUNT(bond_id)) AS average_single_bonded_per_carcinogenic
FROM molecule
JOIN bond ON molecule.molecule_id = bond.molecule_id
WHERE molecule.label = '+'
  AND bond.bond_type = '-';
GROUP BY molecule.molecule_id;

SELECT atom_id FROM atom
JOIN molecule ON atom.molecule_id = molecule.molecule_id
WHERE molecule.label = 'TR186';

SELECT SUM(CASE WHEN T1.bond_type = '-' THEN 1 ELSE 0 END) * 100 / COUNT(T2.atom_id) AS percentage
FROM bond AS T1
JOIN atom AS T2 ON T1.molecule_id = T2.molecule_id;

SELECT COUNT(*) FROM cards AS T1
JOIN legalities AS T2 ON T1.uuid = T2.uuid
WHERE T1.borderColor = 'white' AND T2.status = 'Legal' AND T1.cardKingdomFoilId IS NOT NULL AND T1.cardKingdomId IS NOT NULL;

SELECT CAST(COUNT(CASE WHEN isOnlineOnly = 1 THEN 1 END) AS REAL) * 100 / COUNT(id) AS percentage
FROM cards
WHERE frameEffects = 'legendary';

SELECT COUNT(*) FROM (
    SELECT DISTINCT setCode FROM set_translations WHERE language = 'Japanese'
) AS JapaneseSets
EXCEPT
SELECT DISTINCT setCode FROM sets WHERE mtgoCode IS NOT NULL AND mtgoCode != '';

SELECT subtypes, supertypes
FROM cards
WHERE name = 'Molimo, Maro-Sorcerer';

SELECT name FROM sets
WHERE code IN (
    SELECT setCode FROM set_translations
    WHERE language = 'Korean'
) EXCEPT
SELECT name FROM sets
WHERE code IN (
    SELECT setCode FROM set_translations
    WHERE language LIKE '%Japanese%'
);

SELECT PostHistoryTypeId FROM postHistory WHERE PostId = 3720
UNION
SELECT COUNT(DISTINCT UserId) FROM comments WHERE PostId = 3720;

SELECT AVG(UpVotes) AS AverageUpVotes, AVG(Age) AS AverageAge
FROM users
WHERE COUNT(UserId) > 10;

SELECT COUNT(*) FROM comments
WHERE PostId IN (
    SELECT Id FROM posts WHERE CommentCount = 1
) AND Score = 0;

SELECT AVG(T1.attribute_value) AS average_attribute_value
FROM hero_attribute AS T1
JOIN attribute AS T2 ON T1.attribute_id = T2.id;

SELECT COUNT(T1.id) FROM superhero AS T1
JOIN gender AS T2 ON T1.gender_id = T2.id
WHERE T1.race_id = 21 AND T2.id = 1;

SELECT T1.id FROM superpower AS T1
JOIN hero_power AS T2 ON T1.id = T2.power_id
WHERE T1.power_name = 'cryokinesis';

SELECT COUNT(*) AS drivers_not_finished
FROM results
WHERE date = '2015-11-29' AND time IS NULL;

SELECT COUNT(circuitId) AS circuit_count
FROM circuits
WHERE country = 'Australia' AND location = 'Adelaide';

SELECT AVG(year) AS average_races_per_year
FROM races
WHERE date BETWEEN '2000-01-01' AND '2010-12-31';

SELECT AVG(T1.height) AS average_height
FROM Player AS T1
WHERE T1.birthday >= '1990-01-01 00:00:00' AND T1.birthday < '1996-01-01 00:00:00';

SELECT CAST(COUNT(CASE WHEN Admission = '+' THEN 1 ELSE NULL END) AS REAL) * 100 / COUNT(*) AS InpatientPercentage
FROM Patient
WHERE strftime('%Y', Birthday) BETWEEN '1930' AND '1940';

SELECT COUNT(*) FROM Patient AS T1
JOIN Laboratory AS T2 ON T1.ID = T2.ID
WHERE T1.SEX = 'F' AND year(T1.Description) = '1997' AND T1.Admission = '-';

SELECT COUNT(T1.ID) FROM Patient AS T1
JOIN Examination AS T2 ON T1.ID = T2.ID
WHERE SUBTRACT(YEAR(T2.`Examination Date`), YEAR(T1.`First Date`)) >= 1;

SELECT CAST(COUNT(CASE WHEN T1.U-PRO > 0 AND T1.U-PRO < 30 AND T1.UA <= 6.5 THEN 1 ELSE NULL END) AS REAL) * 100 / COUNT(T1.ID) AS Percentage
FROM Laboratory AS T1
JOIN Patient AS T2 ON T1.ID = T2.ID;

SELECT COUNT(T1.ID) FROM Patient AS T1
JOIN Laboratory AS T2 ON T1.ID = T2.ID
WHERE strftime('%Y', T1.First Date) = '1997' AND T2.tp < 6 OR T2.tp > 8.5;

SELECT DATEDIFF(`Examination Date`, `First Date`) AS DaysBetween
FROM Examination
WHERE ID = 821298;

SELECT AVG(LDH) AS AverageLDH
FROM Laboratory
WHERE LDH < 500;

SELECT COUNT(T1.ID) FROM Patient AS T1
JOIN Laboratory AS T2 ON T1.ID = T2.ID
WHERE T2.CRP = '+' AND T1.Description IS NULL;

SELECT COUNT(DISTINCT T1.ID) FROM Patient AS T1
JOIN Laboratory AS T2 ON T1.ID = T2.ID
WHERE T2.DNA < 8 AND T1.Description IS NULL;

SELECT T1.last_name FROM member AS T1
JOIN major AS T2 ON T1.link_to_major = T2.major_id
WHERE T2.major_name = 'Law and Constitutional Studies';

SELECT SUM(cost) AS total_parking_cost
FROM expense
WHERE expense_description = 'Parking';

SELECT SUM(cost) AS total_expense
FROM expense
WHERE expense_date = '2019-08-20';

SELECT T1.position FROM member AS T1
JOIN major AS T2 ON T1.link_to_major = T2.major_id
WHERE T2.major_name = 'Business';

SELECT CAST(SUM(CASE WHEN T2.remaining < 0 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(T1.event_id) AS percentage_over_budget
FROM event AS T1
JOIN budget AS T2 ON T1.event_id = T2.link_to_event;

SELECT event_id, location, status
FROM event
WHERE event_date BETWEEN '2019-11-01' AND '2020-03-31';

SELECT SUM(CASE WHEN CustomerID = 7 THEN Consumption ELSE 0 END) - SUM(CASE WHEN CustomerID = 5 THEN Consumption ELSE 0 END) AS ConsumptionDifference
FROM yearmonth
WHERE Date LIKE '201304%';

SELECT t2.Description
FROM transactions_1k t1
JOIN products t2 ON t1.ProductID = t2.ProductID;
